SELECT COUNT(DISTINCT student_id) AS ppo_only_students
FROM v_offers_flat
WHERE offer_type = 'PPO' AND student_id NOT IN (
    SELECT student_id FROM v_offers_flat WHERE offer_type = 'FTE'
);

SELECT COUNT(DISTINCT company) AS distinct_companies, COUNT(offer_id) AS total_offers
FROM v_offers_flat
WHERE branch_short_name = 'CE' AND batch_id IN ('2020-2024', '2021-2025', '2022-2026') AND offer_type IN ('FTE', 'PPO', 'Intern+PPO', 'Intern+FTE');

SELECT COUNT(offer_id) AS offers_above_threshold, COUNT(DISTINCT student_id) AS placed_students
FROM v_offers_flat
WHERE ctc_lpa >= 30.0 AND batch_id IN ('2020-2024', '2021-2025', '2022-2026') AND offer_type IN ('FTE', 'PPO', 'Intern+PPO', 'Intern+FTE');

SELECT COUNT(*) AS single_visit_companies FROM (
    SELECT company FROM v_offers_flat GROUP BY company HAVING COUNT(DISTINCT batch_id) = 1
);

SELECT ROUND(AVG(ctc_lpa), 2) AS trimmed_avg_ctc, COUNT(offer_id) AS total_offers
FROM v_offers_flat
WHERE offer_id NOT IN (
    SELECT offer_id FROM v_offers_flat WHERE ctc_lpa IS NOT NULL AND offer_type IN ('FTE', 'PPO', 'Intern+PPO', 'Intern+FTE') ORDER BY ctc_lpa DESC LIMIT 5
) AND ctc_lpa IS NOT NULL AND offer_type IN ('FTE', 'PPO', 'Intern+PPO', 'Intern+FTE');

SELECT ROUND(AVG(ctc_lpa), 2) AS avg_ctc_lpa, MAX(ctc_lpa) AS max_ctc_lpa, MIN(ctc_lpa) AS min_ctc_lpa, COUNT(offer_id) AS total_offers
FROM v_offers_flat
WHERE batch_id IN ('2020-2024', '2021-2025', '2022-2026') AND offer_type IN ('FTE', 'PPO', 'Intern+PPO', 'Intern+FTE') AND ctc_lpa IS NOT NULL AND branch_short_name = 'IT';

SELECT COUNT(offer_id) AS offers_8_to_12, COUNT(DISTINCT student_id) AS placed_students
FROM v_offers_flat
WHERE ctc_lpa BETWEEN 8.0 AND 12.0 AND batch_id IN ('2020-2024', '2021-2025', '2022-2026') AND offer_type IN ('FTE', 'PPO', 'Intern+PPO', 'Intern+FTE');

SELECT ROUND(AVG(ctc_lpa), 2) AS avg_ctc_lpa, MAX(ctc_lpa) AS max_ctc_lpa, MIN(ctc_lpa) AS min_ctc_lpa, COUNT(offer_id) AS total_offers
FROM v_offers_flat
WHERE batch_id IN ('2020-2024', '2021-2025', '2022-2026') AND offer_type IN ('FTE', 'PPO', 'Intern+PPO', 'Intern+FTE') AND ctc_lpa IS NOT NULL AND branch_short_name = 'CSE';

SELECT ROUND(AVG(ctc_lpa), 2) AS avg_ctc_lpa, MAX(ctc_lpa) AS max_ctc_lpa, MIN(ctc_lpa) AS min_ctc_lpa, COUNT(offer_id) AS total_offers
FROM v_offers_flat
WHERE batch_id = '2020-2024' AND offer_type IN ('FTE', 'PPO', 'Intern+PPO', 'Intern+FTE') AND ctc_lpa IS NOT NULL AND branch_short_name = 'CSE';

SELECT COUNT(offer_id) AS software_offers, COUNT(DISTINCT student_id) AS placed_students
FROM v_offers_flat
WHERE branch_short_name = 'EE' AND (sector = 'IT' OR role LIKE '%software%' OR role LIKE '%developer%' OR role LIKE '%analyst%');

SELECT COUNT(offer_id) AS offers_above_threshold, COUNT(DISTINCT student_id) AS placed_students
FROM v_offers_flat
WHERE ctc_lpa >= 50.0 AND batch_id IN ('2020-2024', '2021-2025', '2022-2026') AND offer_type IN ('FTE', 'PPO', 'Intern+PPO', 'Intern+FTE');

SELECT company, branch_short_name, batch_id, role, ctc_lpa
FROM v_offers_flat
WHERE ctc_lpa >= 100.0;

SELECT COUNT(offer_id) AS unpaid_internships, COUNT(DISTINCT student_id) AS placed_students
FROM v_offers_flat
WHERE offer_type = 'Intern' AND (stipend_monthly_inr = 0 OR stipend_monthly_inr IS NULL);
